-- Keeper-Enhanced native PHP API schema. Run in the keeperfx_e database.
-- No accounts or passwords are embedded in this file.
CREATE TABLE IF NOT EXISTS users(id VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,name VARCHAR(24) NOT NULL UNIQUE,salt VARCHAR(32) CHARACTER SET ascii NOT NULL,password VARCHAR(64) CHARACTER SET ascii NOT NULL,public TINYINT NOT NULL DEFAULT 0,created DOUBLE NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cloud_profiles(user VARCHAR(32) CHARACTER SET ascii PRIMARY KEY,email VARCHAR(254) CHARACTER SET ascii COLLATE ascii_bin UNIQUE,avatar INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cloud_signup(ticket CHAR(64) CHARACTER SET ascii PRIMARY KEY,name VARCHAR(24),email VARCHAR(254) CHARACTER SET ascii,salt CHAR(32),password CHAR(64),avatar INT,code CHAR(64),expires DOUBLE,INDEX cloud_signup_expiry(expires)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cloud_email_changes(ticket CHAR(64) CHARACTER SET ascii PRIMARY KEY,user VARCHAR(32) CHARACTER SET ascii NOT NULL,email VARCHAR(254) CHARACTER SET ascii NOT NULL,password CHAR(64) NOT NULL,code CHAR(64) NOT NULL,expires DOUBLE NOT NULL,INDEX cloud_email_expiry(expires)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recovery(user VARCHAR(32) CHARACTER SET ascii,code VARCHAR(64) CHARACTER SET ascii UNIQUE,PRIMARY KEY(user,code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions(token VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,user VARCHAR(32) CHARACTER SET ascii,csrf VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,expires DOUBLE,INDEX session_expiry(expires)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS devices(code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,user_code VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin UNIQUE,user VARCHAR(32) CHARACTER SET ascii,expires DOUBLE,last_poll DOUBLE DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS servers(id VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,name VARCHAR(64),endpoint VARCHAR(150),engine VARCHAR(32),map VARCHAR(80),mods VARCHAR(64),players INT,capacity INT,password TINYINT,region VARCHAR(24),kind VARCHAR(16),owner VARCHAR(32) CHARACTER SET ascii,secret VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,last_seen DOUBLE,status VARCHAR(16),rotation TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS friends(a VARCHAR(32) CHARACTER SET ascii,b VARCHAR(32) CHARACTER SET ascii,status VARCHAR(16),PRIMARY KEY(a,b)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS matches(id VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,server VARCHAR(24) CHARACTER SET ascii,started DOUBLE,ended DOUBLE DEFAULT 0,map VARCHAR(80),engine VARCHAR(32),status VARCHAR(16) DEFAULT 'playing',winner VARCHAR(32) CHARACTER SET ascii DEFAULT '',verification VARCHAR(16) DEFAULT 'casual') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS participants(`match` VARCHAR(32) CHARACTER SET ascii,user VARCHAR(32) CHARACTER SET ascii,result VARCHAR(16) DEFAULT '',PRIMARY KEY(`match`,user)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS events(id VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,owner VARCHAR(32) CHARACTER SET ascii,title VARCHAR(80),kind VARCHAR(16),starts DOUBLE,description TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bracket(event VARCHAR(24) CHARACTER SET ascii,`round` INT,`position` INT,a VARCHAR(32) CHARACTER SET ascii,b VARCHAR(32) CHARACTER SET ascii,winner VARCHAR(32) CHARACTER SET ascii,`match` VARCHAR(32) CHARACTER SET ascii UNIQUE,status VARCHAR(16),PRIMARY KEY(event,`round`,`position`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS entrants(event VARCHAR(24) CHARACTER SET ascii,user VARCHAR(32) CHARACTER SET ascii,PRIMARY KEY(event,user)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS completions(user VARCHAR(32) CHARACTER SET ascii,challenge VARCHAR(24) CHARACTER SET ascii,`match` VARCHAR(32) CHARACTER SET ascii,PRIMARY KEY(user,challenge,`match`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS challenges(id VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,title VARCHAR(80),map VARCHAR(80),description TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tickets(token VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,server VARCHAR(24) CHARACTER SET ascii,user VARCHAR(32) CHARACTER SET ascii,expires DOUBLE,peer INT DEFAULT -1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS identities(`match` VARCHAR(32) CHARACTER SET ascii,peer INT,user VARCHAR(32) CHARACTER SET ascii,PRIMARY KEY(`match`,peer),UNIQUE(`match`,user)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS streams(id VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,server VARCHAR(24) CHARACTER SET ascii,`match` VARCHAR(32) CHARACTER SET ascii,data LONGBLOB,finished TINYINT,engine VARCHAR(32),sequence_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS replays(id VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,`match` VARCHAR(32) CHARACTER SET ascii,owner VARCHAR(32) CHARACTER SET ascii,data LONGBLOB,sha VARCHAR(64) CHARACTER SET ascii,size INT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rate_limits(peer VARCHAR(64) CHARACTER SET ascii,bucket VARCHAR(64) CHARACTER SET ascii,start DOUBLE,count INT,PRIMARY KEY(peer,bucket)) ENGINE=InnoDB;
